from collections import deque
from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def closestKValues(self, root: Optional[TreeNode], target: float, k: int) -> List[int]:
        q = deque()

        def inorder(node: Optional[TreeNode]):
            if not node:
                return
            inorder(node.left)
            if len(q) < k:
                q.append(node.val)
            elif abs(node.val - target) < abs(q[0] - target):
                q.popleft()
                q.append(node.val)
            else:
                return
            inorder(node.right)

        inorder(root)
        return list(q)

class Solution {
    deque<int> q;
    void inorder(TreeNode* node, double target, int k) {
        if (!node) return;
        inorder(node->left, target, k);
        if ((int)q.size() < k) {
            q.push_back(node->val);
        } else if (abs(node->val - target) < abs(q.front() - target)) {
            q.pop_front();
            q.push_back(node->val);
        } else {
            return;
        }
        inorder(node->right, target, k);
    }
public:
    vector<int> closestKValues(TreeNode* root, double target, int k) {
        q.clear();
        inorder(root, target, k);
        return vector<int>(q.begin(), q.end());
    }
};

class Solution {
    private java.util.Deque<Integer> q = new java.util.ArrayDeque<>();
    public List<Integer> closestKValues(TreeNode root, double target, int k) {
        q.clear();
        inorder(root, target, k);
        return new ArrayList<>(q);
    }
    private void inorder(TreeNode node, double target, int k) {
        if (node == null) return;
        inorder(node.left, target, k);
        if (q.size() < k) {
            q.addLast(node.val);
        } else if (Math.abs(node.val - target) < Math.abs(q.peekFirst() - target)) {
            q.removeFirst();
            q.addLast(node.val);
        } else {
            return;
        }
        inorder(node.right, target, k);
    }
}

/**
 * @param {TreeNode} root
 * @param {number} target
 * @param {number} k
 * @return {number[]}
