var closestKValues = function(root, target, k) {
    const q = [];
    function inorder(node) {
        if (node === null) return;
        inorder(node.left);
        if (q.length < k) {
            q.push(node.val);
        } else if (Math.abs(node.val - target) < Math.abs(q[0] - target)) {
            q.shift();
            q.push(node.val);
        } else {
            return;
        }
        inorder(node.right);
    }
    inorder(root);
    return q;
};
